{
  "operations": [
    {
      "op": "set_weight",
      "component": "node_score",
      "feature": "dependency_latency",
      "weight": 0.0
    }
  ],
  "rationale": "The migration budget constraint is violated because services are placed on different nodes than their previous placement, incurring migration penalties. The node_score currently includes dependency_latency with a negative weight, which may favor nodes with lower dependency latency, potentially causing migrations. Setting its weight to 0 removes its influence, allowing other features to determine placement without encouraging migrations.",
  "version": "1.0"
}
